package com.mamtrex.hospital.department;
import com.mamtrex.hospital.organization.Branch; import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="departments", uniqueConstraints=@UniqueConstraint(name="uk_departments_branch_code", columnNames={"branch_id","code"})) public class Department extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="branch_id") private Branch branch; private String code; private String name; private String specialty; private String location; protected Department(){} public Department(Branch branch, String code, String name, String specialty, String location){this.branch=branch; this.code=code; this.name=name; this.specialty=specialty; this.location=location;} public Branch getBranch(){return branch;} public String getCode(){return code;} public String getName(){return name;} public String getSpecialty(){return specialty;} public String getLocation(){return location;} }
